<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Bursar'],true)){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$student=filter_var($_POST['student_id']??null,FILTER_VALIDATE_INT);$term=filter_var($_POST['term_id']??null,FILTER_VALIDATE_INT);$category=filter_var($_POST['category_id']??null,FILTER_VALIDATE_INT);$type=(string)($_POST['transaction_type']??'');$amount=$_POST['amount']??null;$currency=(string)($_POST['currency']??'');$method=(string)($_POST['payment_method']??'');$date=trim((string)($_POST['transaction_date']??date('Y-m-d')));$description=trim((string)($_POST['description']??''));$reference=trim((string)($_POST['external_reference']??''));$rate=trim((string)($_POST['exchange_rate']??''));$types=['Charge','Payment','Adjustment'];$methods=['Cash','EcoCash','Bank transfer','Swipe','Other'];
if(!$student||!in_array($type,$types,true)||!is_numeric($amount)||!in_array($currency,['USD','ZiG'],true)||$description===''||strlen($description)>180||strlen($reference)>100||!valid_fee_txn_date($date)||$date>date('Y-m-d')||($type==='Payment'&&!in_array($method,$methods,true))||($type!=='Payment'&&$method!=='')||($type!=='Adjustment'&&(float)$amount<=0)||($type==='Adjustment'&&(float)$amount==0)||abs((float)$amount)>9999999999.99||($rate!==''&&(!is_numeric($rate)||(float)$rate<=0||(float)$rate>99999999))){$_SESSION['error']='Check the transaction details. Payments need a method; adjustments may be positive or negative.';header('Location: ../?page=fees&student_id='.(int)$student);exit;}
$pdo=db();$check=$pdo->prepare("SELECT st.id FROM students st WHERE st.id=:student AND st.status IN ('Active','Transferred','Withdrawn','Graduated')");$check->execute(['student'=>$student]);if(!$check->fetch()){$_SESSION['error']='Select a valid learner account.';header('Location: ../?page=fees');exit;}
if($term){$check=$pdo->prepare('SELECT id FROM school_terms WHERE id=:id');$check->execute(['id'=>$term]);if(!$check->fetch())$term=null;}
if($category){$check=$pdo->prepare('SELECT id FROM fee_categories WHERE id=:id');$check->execute(['id'=>$category]);if(!$check->fetch())$category=null;}
try{$pdo->beginTransaction();$stmt=$pdo->prepare('INSERT INTO fee_ledger (student_id,term_id,category_id,transaction_type,description,amount,currency,exchange_rate,payment_method,external_reference,transaction_date,recorded_by) VALUES (:student,:term,:category,:type,:description,:amount,:currency,:rate,:method,:reference,:date,:user)');$stmt->execute(['student'=>$student,'term'=>$term,'category'=>$category,'type'=>$type,'description'=>$description,'amount'=>number_format((float)$amount,2,'.',''),'currency'=>$currency,'rate'=>$rate!==''?number_format((float)$rate,6,'.',''):null,'method'=>$method?:null,'reference'=>$reference?:null,'date'=>$date,'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();if($type==='Payment'){$schoolCode=$pdo->query('SELECT school_code FROM school_profile WHERE id=1')->fetchColumn();$prefix=strtoupper(substr(trim(preg_replace('/[^A-Z0-9-]/i','',(string)$schoolCode),'-'),0,14));if($prefix==='')$prefix='SCHOOL';$receipt=$prefix.'-'.substr($date,0,4).'-'.str_pad((string)$id,7,'0',STR_PAD_LEFT);$up=$pdo->prepare('UPDATE fee_ledger SET receipt_no=:receipt WHERE id=:id');$up->execute(['receipt'=>$receipt,'id'=>$id]);}audit_log('fees.transaction_recorded','fee_ledger',$id,['type'=>$type,'currency'=>$currency]);$pdo->commit();$_SESSION['notice']=$type==='Payment'?'Payment recorded; receipt issued.':'Fee transaction recorded.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Fee transaction save failed: '.$e->getMessage());$_SESSION['error']='Could not record the transaction.';}
header('Location: ../?page=fees&student_id='.(int)$student);exit;
function valid_fee_txn_date(string $date):bool{if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))return false;$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date);$e=DateTimeImmutable::getLastErrors();return $d!==false&&$d->format('Y-m-d')===$date&&($e===false||(!$e['warning_count']&&!$e['error_count']));}
